[归一化后的问题]
T_A 自 2026-08-01 起各大区各店铺的 GMV 分别是多少？

[已审查的查询计划]
{
  "assets": [
    {
      "asset": "order_paid",
      "join_key": null
    },
    {
      "asset": "region",
      "join_key": "order_paid.region_code = region.code"
    },
    {
      "asset": "shop",
      "join_key": "order_paid.shop_id = shop.shop_id"
    }
  ],
  "blocking_issues": [],
  "dimensions": [
    "region.region_name",
    "shop.shop_name"
  ],
  "filters": [
    "order_paid.pay_time >= '2026-08-01'",
    "order_paid.pay_status = '已支付'",
    "order_paid.is_test_order = false"
  ],
  "grain": "shop",
  "limit": 1000,
  "metrics": [
    {
      "caliber": "口径未在语义包指标目录中登记（本次未提供指标口径目录）。按语义包登记的时间基准 order_paid.pay_time 统计，取 order_paid.pay_amount（实付金额，含运费、扣除优惠后）求和；是否剔除退款/测试单需口径确认，本计划按已支付且非测试单过滤。",
      "name": "GMV"
    }
  ],
  "order_by": [
    "region.region_name asc",
    "GMV desc"
  ],
  "output_columns": [
    "region_name",
    "shop_name",
    "gmv"
  ],
  "time_range": {
    "end": null,
    "start": "2026-08-01"
  }
}

